"""Weekly timesheet lines built from a list of shifts."""

from typing import Dict, List, Tuple

from hourglass.models import Shift


def _check(shifts: List[Shift]) -> None:
    if not shifts:
        raise ValueError("no shifts given")
    for shift in shifts:
        if not shift.worker.strip():
            raise ValueError("blank worker name")


def _tally(shifts: List[Shift]) -> Dict[str, Tuple[int, int]]:
    stats = {}
    for shift in shifts:
        count, mins = stats.get(shift.worker, (0, 0))
        stats[shift.worker] = (
            count + 1, mins + shift.span.minutes)
    return stats


def _busyness(item: Tuple[str, Tuple[int, int]]) -> tuple:
    name, (count, minutes) = item
    return (-minutes, -count, name)


def _line(name: str, count: int, minutes: int) -> str:
    hours = minutes / 60
    return f"{name}: shifts={count} hours={hours:.1f}"


# ---
def timesheet_lines(shifts: List[Shift]) -> List[str]:
    """One line per worker, busiest first. ValueError on bad input."""
    _check(shifts)
    ranked = sorted(_tally(shifts).items(), key=_busyness)
    return [_line(name, *vals) for name, vals in ranked]
