cat > tests/test_timesheet.py <<'EOF'
import unittest

from hourglass.timesheet import timesheet_lines
from hourglass.models import Shift, Span


def make_shift(worker: str, start: int, end: int) -> Shift:
    return Shift(worker, "mon", Span(start * 60, end * 60))


class TimesheetTests(unittest.TestCase):
    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            timesheet_lines([])

    def test_blank_worker_raises(self):
        for name in ("", "   "):
            with self.assertRaises(ValueError):
                timesheet_lines([make_shift(name, 8, 12)])

    def test_one_line_per_worker(self):
        lines = timesheet_lines(
            [make_shift("Ada", 8, 12), make_shift("Ada", 13, 17)]
        )
        self.assertEqual(lines, ["Ada: shifts=2 hours=8.0"])

    def test_busiest_first(self):
        lines = timesheet_lines(
            [
                make_shift("Bob", 8, 10),
                make_shift("Cy", 8, 16),
                make_shift("Ada", 8, 10),
            ]
        )
        self.assertEqual(
            lines,
            [
                "Cy: shifts=1 hours=8.0",
                "Ada: shifts=1 hours=2.0",
                "Bob: shifts=1 hours=2.0",
            ],
        )

    def test_one_decimal_place(self):
        shift = Shift("Ada", "tue", Span(540, 620))
        self.assertEqual(
            timesheet_lines([shift]), ["Ada: shifts=1 hours=1.3"]
        )


if __name__ == "__main__":
    unittest.main()
